"use client";

import { useEffect, useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { SettingsSection } from "@/components/account/Settingssection";
import { Copy, Plus, Trash2, KeyRound } from "lucide-react";
import { toast } from "sonner";
import { useSession } from "next-auth/react";
import { withBearerToken } from "@/lib/fetch-auth";
import { headers } from "next/dist/server/request/headers";

type PlatformApiKey = {
  id: string;
  name: string;
  prefix: string;
  scopes: unknown;
  usageCount: number;
  lastUsedAt: string | null;
  expiresAt: string | null;
  revokedAt: string | null;
  createdAt: string;
  updatedAt: string;
};

const AVAILABLE_SCOPES = [
  { value: "platform:read", label: "Read all platform data" },
  { value: "platform:users", label: "User directory" },
  { value: "platform:apps", label: "Applications" },
  { value: "platform:storage", label: "Storage usage" },
  { value: "platform:sessions", label: "Active sessions" },
] as const;

function parseScopes(scopes: unknown) {
  return Array.isArray(scopes) ? scopes.filter((scope): scope is string => typeof scope === "string") : [];
}

function formatDate(value: string | null) {
  if (!value) return "Never";
  return new Intl.DateTimeFormat("en-AU", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value));
}

export function PlatformApiKeysSection() {
  const [keys, setKeys] = useState<PlatformApiKey[]>([]);
  const [loading, setLoading] = useState(true);
  const [name, setName] = useState("Default platform API key");
  const [selectedScopes, setSelectedScopes] = useState<string[]>(["platform:read"]);
  const [expiresAt, setExpiresAt] = useState("");
  const [creating, setCreating] = useState(false);
  const [generatedKey, setGeneratedKey] = useState<string | null>(null);

  const session = useSession();

  const visibleKeys = useMemo(() => keys, [keys]);

  const loadKeys = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${process.env.NEXT_PUBLIC_API_HOST}/api/platform/account/keys`, {
        headers: { "Content-Type": "application/json" },
        ...withBearerToken(undefined, session.data?.accessToken),
      });
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error ?? "Failed to load API keys");
      }

      setKeys(data.keys ?? []);
    } catch (error) {
      console.error(error);
      toast.error("Could not load API keys");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadKeys();
  }, []);

  const toggleScope = (scope: string) => {
    setSelectedScopes((current) =>
      current.includes(scope)
        ? current.filter((value) => value !== scope)
        : [...current, scope],
    );
  };

  const handleCreateKey = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    setCreating(true);
    setGeneratedKey(null);

    try {
      const response = await fetch(`${process.env.NEXT_PUBLIC_API_HOST}/api/platform/account/keys`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        ...withBearerToken(undefined, session.data?.accessToken),
        body: JSON.stringify({
          name,
          scopes: selectedScopes,
          expiresAt: expiresAt ? new Date(expiresAt).toISOString() : null,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error ?? "Failed to create API key");
      }

      setGeneratedKey(data.apiKey);
      toast.success("Platform API key created");
      await loadKeys();
    } catch (error) {
      console.error(error);
      toast.error(error instanceof Error ? error.message : "Could not create API key");
    } finally {
      setCreating(false);
    }
  };

  const handleRevoke = async (keyId: string) => {
    if (!confirm("Revoke this API key? Existing integrations using it will stop working.")) {
      return;
    }

    try {
      const response = await fetch(`${process.env.NEXT_PUBLIC_API_HOST}/api/platform/account/keys/${keyId}`, {
        method: "DELETE",
        ...withBearerToken(undefined, session.data?.accessToken),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error ?? "Failed to revoke API key");
      }

      toast.success("API key revoked");
      await loadKeys();
    } catch (error) {
      console.error(error);
      toast.error("Could not revoke API key");
    }
  };

  return (
    <div className="flex flex-col gap-8">
      <SettingsSection
        tag="Platform API"
        title="Create and manage API keys"
        description="Generate scoped keys for your own services. Keys are shown once and stored hashed in the database."
      >
        <Card className="bg-background/35 backdrop-blur-md border-border/60">
          <CardContent className="pt-6 space-y-6">
            <form className="space-y-5" onSubmit={handleCreateKey}>
              <div className="space-y-1.5">
                <Label htmlFor="api-key-name" className="text-xs text-muted-foreground">
                  Key name
                </Label>
                <Input
                  id="api-key-name"
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  className="bg-background/50"
                  placeholder="Production integration"
                />
              </div>

              <div className="space-y-2">
                <p className="text-xs text-muted-foreground">Scopes</p>
                <div className="grid gap-2 md:grid-cols-2">
                  {AVAILABLE_SCOPES.map((scope) => (
                    <button
                      key={scope.value}
                      type="button"
                      onClick={() => toggleScope(scope.value)}
                      className={`rounded-lg border px-3 py-2 text-left text-sm transition-colors ${
                        selectedScopes.includes(scope.value)
                          ? "border-primary/40 bg-primary/10 text-foreground"
                          : "border-border/60 bg-background/30 text-muted-foreground hover:text-foreground"
                      }`}
                    >
                      <div className="font-medium">{scope.label}</div>
                      <div className="text-xs opacity-70">{scope.value}</div>
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="api-key-expiry" className="text-xs text-muted-foreground">
                  Expiry date and time
                </Label>
                <Input
                  id="api-key-expiry"
                  type="datetime-local"
                  value={expiresAt}
                  onChange={(event) => setExpiresAt(event.target.value)}
                  className="bg-background/50"
                />
              </div>

              <div className="flex justify-end">
                <Button type="submit" disabled={creating} className="gap-2">
                  <Plus className="h-4 w-4" />
                  {creating ? "Creating..." : "Generate key"}
                </Button>
              </div>
            </form>

            {generatedKey && (
              <div className="rounded-xl border border-primary/30 bg-primary/5 p-4 space-y-3">
                <div className="flex items-center gap-2 text-sm font-medium text-foreground">
                  <KeyRound className="h-4 w-4" />
                  Copy this key now. It will not be shown again.
                </div>
                <div className="flex flex-col gap-3 md:flex-row md:items-center">
                  <code className="break-all rounded-lg border border-border/60 bg-background/70 px-3 py-2 text-xs text-muted-foreground">
                    {generatedKey}
                  </code>
                  <Button
                    variant="outline"
                    size="sm"
                    className="gap-2"
                    onClick={async () => {
                      await navigator.clipboard.writeText(generatedKey);
                      toast.success("API key copied");
                    }}
                  >
                    <Copy className="h-4 w-4" />
                    Copy
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </SettingsSection>

      <SettingsSection
        tag="Active Keys"
        title="Configured API keys"
        description="Use these keys in the x-api-key header or as a Bearer token when calling platform routes."
      >
        <Card className="bg-background/35 backdrop-blur-md border-border/60">
          <CardContent className="pt-6 space-y-4">
            {loading ? (
              <p className="text-sm text-muted-foreground">Loading keys...</p>
            ) : visibleKeys.length === 0 ? (
              <p className="text-sm text-muted-foreground">No API keys have been created yet.</p>
            ) : (
              <div className="space-y-4">
                {visibleKeys.map((key) => {
                  const isRevoked = Boolean(key.revokedAt);

                  return (
                  <div key={key.id} className="rounded-xl border border-border/60 bg-background/40 p-4">
                    <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
                      <div className="space-y-2">
                        <div className="flex flex-wrap items-center gap-2">
                          <h3 className="font-medium text-foreground">{key.name}</h3>
                          <Badge variant="outline" className="text-[10px] uppercase tracking-wide">
                            {key.prefix}
                          </Badge>
                          <Badge
                            variant={isRevoked ? "destructive" : "secondary"}
                            className="text-[10px] uppercase tracking-wide"
                          >
                            {isRevoked ? "Revoked" : "Active"}
                          </Badge>
                        </div>
                        <p className="text-xs text-muted-foreground">
                          Created {formatDate(key.createdAt)} ┬À Last used {formatDate(key.lastUsedAt)}
                        </p>
                        <p className="text-xs text-muted-foreground">Usage count: {key.usageCount}</p>
                        <div className="flex flex-wrap gap-2 pt-1">
                          {parseScopes(key.scopes).map((scope) => (
                            <Badge key={scope} variant="secondary" className="text-[10px]">
                              {scope}
                            </Badge>
                          ))}
                        </div>
                      </div>
                      <Button
                        variant="destructive"
                        size="sm"
                        className="gap-2"
                        onClick={() => handleRevoke(key.id)}
                        disabled={isRevoked}
                      >
                        <Trash2 className="h-4 w-4" />
                        {isRevoked ? "Revoked" : "Revoke"}
                      </Button>
                    </div>
                  </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </SettingsSection>
    </div>
  );
}

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { AccountSettingsForm } from "@/components/account/account-settings-form";
import { DetailRow, SettingsSection } from "@/components/account/Settingssection";
import { Upload } from "lucide-react";
import type { AccountUser } from "./types";

interface ProfileSectionProps {
  user: AccountUser | null;
  initials: string;
  sessionName?: string | null;
  sessionEmail?: string | null;
  formatDate: (d: Date) => string;
}

export function ProfileSection({
  user,
  initials,
  sessionName,
  sessionEmail,
  formatDate,
}: ProfileSectionProps) {
  const primaryMailbox =
    user?.mailboxes?.find((m) => m.isPrimary) ?? user?.mailboxes?.[0];

  return (
    <div className="flex flex-col gap-8">
      <SettingsSection
        tag="Profile"
        title="Public profile"
        description="This is how others see you across Fortmont ÔÇö in tickets, comments, and audit logs."
      >
        <Card className="bg-background/35 backdrop-blur-md border-border/60">
          <CardContent className="pt-6 space-y-6">
            {/* Avatar row */}
            <div className="flex items-center gap-4">
              <div className="relative group cursor-pointer">
                <Avatar className="h-16 w-16 rounded-2xl">
                  <AvatarImage
                    src={user?.avatarUrl ?? "/defaults/profile_default.jpg"}
                    alt={user?.displayName ?? "Account"}
                  />
                 
                    
                </Avatar>
                <div className="absolute inset-0 flex items-center justify-center rounded-2xl bg-black/50 opacity-0 transition-opacity group-hover:opacity-100">
                  <Upload className="h-4 w-4 text-white" />
                </div>
              </div>
              <div className="space-y-1">
                <p className="text-sm font-medium">Profile photo</p>
                <p className="text-xs text-muted-foreground">JPG or PNG ┬À max 2 MB</p>
                <Button variant="outline" size="sm" className="mt-1 h-7 text-xs">
                  <Upload className="mr-1.5 h-3 w-3" />
                  Upload photo
                </Button>
              </div>
            </div>

            <Separator className="opacity-50" />

            {user ? (
              <AccountSettingsForm
                user={{
                  id: user.id,
                  displayName: user.displayName,
                  email: user.email,
                  phone: user.phone,
                  avatarUrl: user.avatarUrl,
                }}
                hasMailbox={(user.mailboxes?.length ?? 0) > 0}
              />
            ) : (
              <div className="space-y-2 text-sm text-muted-foreground">
                <p>No database account matched this session.</p>
              </div>
            )}
          </CardContent>
        </Card>
      </SettingsSection>

      <SettingsSection
        tag="Identity"
        title="Account details"
        description="Read-only identity and lifecycle metadata."
      >
        <Card className="bg-background/35 backdrop-blur-md border-border/60">
          <CardContent className="pt-6 divide-y divide-border/40">
            {user ? (
              <>
                <DetailRow label="User ID" value={user.id} mono />
                <DetailRow label="Username" value={user.username} />
              </>
            ) : (
              <DetailRow label="Account link" value="No database match" />
            )}
            <DetailRow
              label="Display name"
              value={user?.displayName ?? sessionName ?? "Not set"}
            />
            <DetailRow
              label="Email"
              value={user?.email ?? sessionEmail ?? "Not set"}
            />
            <DetailRow label="Phone" value={user?.phone ?? "Not set"} />
            <div className="flex items-center justify-between gap-4 py-1.5">
              <span className="shrink-0 text-sm text-muted-foreground">Status</span>
              <Badge variant={user?.isActive ? "default" : "secondary"}>
                {user?.isActive ? "Active" : "Pending"}
              </Badge>
            </div>
            <div className="flex items-center justify-between gap-4 py-1.5">
              <span className="shrink-0 text-sm text-muted-foreground">Account type</span>
              <Badge variant="outline">
                {user?.isEntraUser ? "Microsoft Entra" : "Local account"}
              </Badge>
            </div>
            <div className="flex items-center justify-between gap-4 py-1.5">
              <span className="shrink-0 text-sm text-muted-foreground">Role</span>
              <Badge variant="secondary">{user?.role ?? "No role set"}</Badge>
            </div>
            {user && (
              <>
                <DetailRow label="Created" value={formatDate(user.createdAt)} />
                <DetailRow
                  label="Last login"
                  value={user.lastLoggedIn ? formatDate(user.lastLoggedIn) : "Never"}
                />
                <DetailRow label="Last updated" value={formatDate(user.updatedAt)} />
              </>
            )}
            <DetailRow
              label="Primary mailbox"
              value={primaryMailbox?.email ?? "No mailbox provisioned"}
            />
            <DetailRow
              label="Teams"
              value={user?.teams?.length ? `${user.teams.length} joined` : "None"}
            />
          </CardContent>
        </Card>
      </SettingsSection>
    </div>
  );
}

