type SortKey = "name" | "size";

export async function getDownloadUrl(fileId: string, accessToken?: string): Promise<string> {
  const res = await fetch(
    `${process.env.NEXT_PUBLIC_API_HOST}/api/storage/download?fileId=${encodeURIComponent(fileId)}`,
    withBearerToken(undefined, accessToken),
  );
  const data = await res.json();
  const url = data.downloadUrl ?? data.url;
  if (!url) throw new Error("No download URL returned");
  return url;
}

export async function downloadFile(file: StorageFile, accessToken?: string): Promise<void> {
  const url = await getDownloadUrl(file.id, accessToken);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = file.name;
  anchor.rel = "noopener";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
}

async function handleDownload(file: StorageFile, accessToken?: string) {
  try {
    await downloadFile(file, accessToken);
  } catch (error) {
    toast.error("Download failed", {
      description: error instanceof Error ? error.message : "Unexpected error",
    });
  }
}
 
const deleteFile = async (fileId: string, accessToken?: string) => {

  await fetch(`${process.env.NEXT_PUBLIC_API_HOST}/api/storage/delete/file/${fileId}`, {
    method: "DELETE",
    ...withBearerToken(undefined, accessToken),
  }).then((res) => {
    if (!res.ok) {
      throw new Error("Failed to delete file");
    }
  }).catch(() => {
    toast.error("Failed to delete file", {
      description: "An error occurred while trying to delete the file.",
    });
  });
}



function FileActions({ file }: { file: StorageFile }) {
    const router = useRouter();
  const { data: session } = useSession();
    const handleDelete = async (fileId: string) => {
  await deleteFile(fileId, session?.accessToken);
 
  
  router.refresh(); 
  toast.success("File deleted ");
}

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="icon" className="h-8 w-8">
          <MoreVertical className="h-4 w-4" />
          <span className="sr-only">Actions</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onClick={() => handleDownload(file, session?.accessToken)}>
          <Download className="h-4 w-4" />
          Download
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={() => {
            navigator.clipboard.writeText(file.id);
            toast.success("File ID copied");
          }}
        >
          <Copy className="h-4 w-4" />
          Copy file ID
        </DropdownMenuItem>
        <DropdownMenuItem className="hover:bg-destructive/100"     
          onClick={() => handleDelete(file.id)}
        >
          Delete
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function FileCard({ file }: { file: StorageFile }) {
  const ext = getFileExtension(file.name);
