              background: "#0a0a0a",
              borderRadius: "16px",
              border: "0.5px solid rgba(255,255,255,0.08)",
              overflow: "hidden",
              animation: "vp-pop 0.22s cubic-bezier(0.34, 1.56, 0.64, 1) both",
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={() => closeDialog()}
